import type {
  MedusaRequest,
  MedusaResponse,
} from "@medusajs/framework/http"
import { orderClaimAddNewItemWorkflow } from "@medusajs/medusa/core-flows"

export async function POST(
  req: MedusaRequest,
  res: MedusaResponse
) {
  const { result } = await orderClaimAddNewItemWorkflow(req.scope)
    .run({
      input: {
        claim_id: "claim_123",
        items: [{
          variant_id: "variant_123",
          quantity: 1
        }]
      }
    })

  res.send(result)
}

